static const AccGlyph *acc_find(const char *s, int n, bool large) {
  const AccGlyph *t = large ? ACC_LARGE : ACC_SMALL;
  unsigned cnt = large ? sizeof ACC_LARGE / sizeof ACC_LARGE[0] : sizeof ACC_SMALL / sizeof ACC_SMALL[0];
  for (unsigned i = 0; i < cnt; i++)
    if ((int)strlen(t[i].utf8) == n && memcmp(s, t[i].utf8, n) == 0) return &t[i];
  return 0;
}

/* Dessine seulement l'accent. Si la lettre n'a pas de base (œ), la cellule est remplie
 * avec le fond puis le glyphe complet est tracé. La lettre nue est dessinée par main.c. */
static void acc_draw_marks(const AccGlyph *g, int x, int y, bool large, eadk_color_t fg, eadk_color_t bg) {
  int w = large ? ACC_LARGE_W : ACC_SMALL_W;
  int h = large ? ACC_LARGE_H : ACC_SMALL_H;
  int dy = large ? ACC_LARGE_DY : ACC_SMALL_DY;
  /* L'accent aigu (é, É) est déjà bien placé : pas de décalage */
  bool acute = strcmp(g->utf8, "\xc3\xa9") == 0 || strcmp(g->utf8, "\xc3\x89") == 0;
  int dx = acute ? 0 : (large ? ACC_LARGE_DX : ACC_SMALL_DX);
  x += dx;
  if (!g->base)
    eadk_display_push_rect_uniform((eadk_rect_t){ (uint16_t)x, (uint16_t)(y + dy), (uint16_t)w, (uint16_t)h }, bg);
  for (int r = 0; r < h; r++)
    for (int c = 0; c < w; c++)
      if (g->rows[r] & (1u << (w - 1 - c)))
        eadk_display_push_rect_uniform((eadk_rect_t){ (uint16_t)(x + c), (uint16_t)(y + dy + r), 1, 1 }, fg);
}

